-- 目录种子数据：门店、分类、商品、规格组与规格选项
-- 不含任何订单；商品图片引用（products.image_path）不在此维护，由人工上传图片后填入。
-- 数据来源：Phase 1 的 mp/src/mock/products.ts 与 mp/src/mock/store.ts（store 属 Story 1.3）。
-- uuid 规则：末 12 位为编号 —— 000000000001 门店、0000000001NN 分类、0000000002NN 商品、
--            0000000003NN 规格组、0000000004NN 规格选项。

values (
  '00000000-0000-4000-8000-000000000001',
  '星巴克 啡快自提店',
  '北京市朝阳区创意产业园 A 座 1 层',
  '010-88888888',
  'Asia/Shanghai'
);

-- 分类
;

-- 商品（availability 默认 on_sale；售罄/下架样例见文件末尾的 update）
;

-- 规格组（全局字典，multi 标记多选）
;

-- 规格选项（price_extra 既是展示价也是计价来源）
;

-- 商品 ↔ 规格组（sort_order 决定规格摘要的顺序）
;

-- 可售状态样例：一例售罄、一例下架。
-- 下架的是「周边好物」唯一的商品，使该分类在过滤后整体不返回（Story 1.6 可验证）。
update public.products set availability = 'sold_out' where id = '00000000-0000-4000-8000-000000000233'; -- 提拉米苏
update public.products set availability = 'delisted' where id = '00000000-0000-4000-8000-000000000251'; -- 城市随行杯
